namespace Controllers.Network
{
    public interface INetworkIdentity
    {
        bool IsMine { get; }
        bool IsMasterClient { get; }
        int ViewID { get; }
    }

    public interface INetworkRPC
    {
        void RPC(string methodName, NetworkTarget target, params object[] args);
    }

    public enum NetworkTarget
    {
        All,
        Others,
        MasterClient,
        AllBuffered
    }
}

using Controllers.Services;
using Photon.Pun;
using UnityEngine;

namespace Controllers.Network
{
    public class PhotonObjectService : INetworkObjectService
    {
        public GameObject Instantiate(string prefabName, Vector3 position, Quaternion rotation)
        {
            return PhotonNetwork.Instantiate(prefabName, position, rotation);
        }

        public GameObject InstantiateRoomObject(string prefabName, Vector3 position, Quaternion rotation)
        {
            return PhotonNetwork.InstantiateRoomObject(prefabName, position, rotation);
        }

        public void InvokeRPC(MonoBehaviour source, string methodName, NetworkTarget target, params object[] parameters)
        {
            PhotonView photonView = source.GetComponent<PhotonView>();
            if (photonView == null)
            {
                Debug.LogWarning($"[PhotonObjectService] {source.name} 上没有 PhotonView 组件，无法调用 RPC {methodName}");
                return;
            }
            photonView.RPC(methodName, NetworkTargetMapper.ToRpcTarget(target), parameters);
        }

        public int GetViewID(Component component)
        {
            PhotonView photonView = component.GetComponent<PhotonView>();
            return photonView != null ? photonView.ViewID : -1;
        }

        public int GetViewID(GameObject gameObject)
        {
            if (gameObject == null) return -1;
            PhotonView photonView = gameObject.GetComponent<PhotonView>();
            return photonView != null ? photonView.ViewID : -1;
        }

        public GameObject FindByViewID(int viewId)
        {
            PhotonView photonView = PhotonView.Find(viewId);
            return photonView != null ? photonView.gameObject : null;
        }

        public string GetOwnerNickname(MonoBehaviour source)
        {
            if (source == null) return "";
            PhotonView pv = source.GetComponentInParent<PhotonView>();
            return pv != null && pv.Owner != null ? pv.Owner.NickName : "";
        }

        public int GetOwnerActorNumber(Component source)
        {
            if (source == null) return -1;
            PhotonView pv = source.GetComponentInParent<PhotonView>();
            return pv != null && pv.Owner != null ? pv.Owner.ActorNumber : -1;
        }
    }
}

using System.Collections.Generic;
using Controllers.Services;
using Photon.Pun;
using Photon.Realtime;
using UnityEngine;

namespace Controllers.Network
{
    public class PhotonPlayerService : INetworkPlayerService
    {
        private readonly Dictionary<int, Photon.Realtime.Player> _playerCache = new();

        public event System.Action<int, string, object> OnPlayerPropertyChanged;
        public event System.Action<int, string> OnPlayerEnteredRoom;
        public event System.Action<int, string> OnPlayerLeftRoom;
        public event System.Action OnLocalJoinedRoom;

        public bool IsConnectedAndInRoom => PhotonNetwork.IsConnectedAndReady && PhotonNetwork.InRoom;
        public bool IsMasterClient => PhotonNetwork.IsMasterClient;

        public int GetLocalActorNumber()
        {
            if (PhotonNetwork.LocalPlayer != null)
                return PhotonNetwork.LocalPlayer.ActorNumber;
            return -1;
        }

        public string GetLocalUserId()
        {
            if (PhotonNetwork.LocalPlayer != null)
                return PhotonNetwork.LocalPlayer.UserId;
            return string.Empty;
        }

        public bool IsOwnerOf(GameObject gameObject)
        {
            if (gameObject == null) return false;
            PhotonView pv = gameObject.GetComponentInParent<PhotonView>();
            return pv != null && pv.IsMine;
        }

        public void SetCustomProperty(string key, object value)
        {
            if (!IsConnectedAndInRoom) return;
            var props = new ExitGames.Client.Photon.Hashtable { { key, value } };
            PhotonNetwork.LocalPlayer.SetCustomProperties(props);
        }

        public object GetCustomProperty(string key)
        {
            if (!IsConnectedAndInRoom || PhotonNetwork.LocalPlayer == null)
                return null;
            return PhotonNetwork.LocalPlayer.CustomProperties[key];
        }

        public int[] GetAllActorNumbers()
        {
            if (!IsConnectedAndInRoom) return System.Array.Empty<int>();
            var players = PhotonNetwork.PlayerList;
            int[] actorNumbers = new int[players.Length];
            for (int i = 0; i < players.Length; i++)
            {
                actorNumbers[i] = players[i].ActorNumber;
            }
            return actorNumbers;
        }

        public object GetPlayerCustomProperty(int actorNumber, string key)
        {
            if (!IsConnectedAndInRoom) return null;
            var player = FindPlayer(actorNumber);
            return player != null ? player.CustomProperties[key] : null;
        }

        public string GetPlayerUserId(int actorNumber)
        {
            if (!IsConnectedAndInRoom) return null;
            var player = FindPlayer(actorNumber);
            return player != null ? player.UserId : null;
        }

        public string GetPlayerNickName(int actorNumber)
        {
            if (!IsConnectedAndInRoom) return null;
            var player = FindPlayer(actorNumber);
            return player != null ? player.NickName : null;
        }

        public bool AllPlayersHaveProperty(string key, object value)
        {
            if (!IsConnectedAndInRoom) return false;
            foreach (var player in PhotonNetwork.PlayerList)
            {
                if (!player.CustomProperties.ContainsKey(key))
                    return false;
                if (!player.CustomProperties[key].Equals(value))
                    return false;
            }
            return true;
        }

        public void SetRoomCustomProperty(string key, object value)
        {
            if (!IsConnectedAndInRoom || PhotonNetwork.CurrentRoom == null) return;
            var props = new ExitGames.Client.Photon.Hashtable { { key, value } };
            PhotonNetwork.CurrentRoom.SetCustomProperties(props);
        }

        public object GetRoomCustomProperty(string key)
        {
            if (!IsConnectedAndInRoom || PhotonNetwork.CurrentRoom == null)
                return null;
            return PhotonNetwork.CurrentRoom.CustomProperties[key];
        }

        /// <summary>
        /// 由 PhotonCallbackBridge 调用，转发 PUN 属性变更事件
        /// </summary>
        public void NotifyPropertyChanged(int actorNumber, string key, object value)
        {
            OnPlayerPropertyChanged?.Invoke(actorNumber, key, value);
        }

        /// <summary>
        /// 由 PhotonCallbackBridge 调用，转发玩家加入事件
        /// </summary>
        public void NotifyPlayerEnteredRoom(int actorNumber, string userId)
        {
            var player = FindPlayer(actorNumber);
            if (player != null)
                _playerCache[actorNumber] = player;
            OnPlayerEnteredRoom?.Invoke(actorNumber, userId);
        }

        /// <summary>
        /// 由 PhotonCallbackBridge 调用，转发玩家离开事件
        /// </summary>
        public void NotifyPlayerLeftRoom(int actorNumber, string userId)
        {
            _playerCache.Remove(actorNumber);
            OnPlayerLeftRoom?.Invoke(actorNumber, userId);
        }

        /// <summary>
        /// 由 PhotonCallbackBridge 调用，转发本地玩家加入完成事件
        /// </summary>
        public void NotifyLocalJoinedRoom()
        {
            _playerCache.Clear();
            foreach (var player in PhotonNetwork.PlayerList)
                _playerCache[player.ActorNumber] = player;
            OnLocalJoinedRoom?.Invoke();
        }

        private Photon.Realtime.Player FindPlayer(int actorNumber)
        {
            if (_playerCache.TryGetValue(actorNumber, out var cached))
                return cached;
            foreach (var player in PhotonNetwork.PlayerList)
            {
                if (player.ActorNumber == actorNumber)
                {
                    _playerCache[actorNumber] = player;
                    return player;
                }
            }
            return null;
        }
    }
}

using Controllers.Character;
using Controllers.Character.Pets;
using Controllers.Enemy;
using Core;
using Controllers.Item;
using Controllers.Services;
using Controllers.Time;
using Photon.Pun;
using UnityEngine;

namespace Controllers.Network
{
    /// <summary>
    /// Domain 层 RPC 桥接器（Infrastructure 层）
    /// 统一持有所有 Domain 层的 [PunRPC] 方法，通过公共方法委托回 Domain 对象
    /// 职责：纯粹的 RPC 转发，不包含业务逻辑
    /// </summary>
    public class DomainRpcBridge : MonoBehaviourPun, IDomainRpcService
    {
        public static DomainRpcBridge Instance { get; private set; }

        private SpiderBoss _spiderBossCache;

        /// <summary>注册场景中的 SpiderBoss 引用，避免每次 RPC 都做 FindObjectsByType</summary>
        public void RegisterSpiderBoss(SpiderBoss boss) => _spiderBossCache = boss;

        /// <summary>清除 SpiderBoss 缓存（Boss 销毁时调用）</summary>
        public void ClearSpiderBossCache() => _spiderBossCache = null;

        private SpiderBoss GetSpiderBoss()
        {
            // Unity 的 == 重载会在对象销毁后返回 true，所以这里天然支持缓存失效
            if (_spiderBossCache != null)
                return _spiderBossCache;
            var bosses = FindObjectsByType<SpiderBoss>(FindObjectsSortMode.None);
            if (bosses.Length > 0)
                _spiderBossCache = bosses[0];
            return _spiderBossCache;
        }

        void Awake()
        {
            if (Instance != null)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;
            DontDestroyOnLoad(gameObject);

            // 注册到 NetworkServiceLocator，供 Domain 层通过接口调用
            NetworkServiceLocator.RegisterDomainRpcService(this);
        }

        void OnDestroy()
        {
            if (Instance == this)
            {
                Instance = null;
            }
        }

        // ============================================================
        // SyncedGameTimeManager RPC
        // ============================================================

        [PunRPC]
        public void RPC_SyncStartCaTime()
        {
            SyncedGameTimeManager.HandleSyncStartCaTime();
        }

        [PunRPC]
        public void RPC_OnTimeEventTriggered(string eventId, float triggerTime)
        {
            SyncedGameTimeManager.HandleOnTimeEventTriggered(eventId, triggerTime);
        }

        [PunRPC]
        public void RPC_GameTimeFinished()
        {
            SyncedGameTimeManager.HandleGameTimeFinished();
        }

        [PunRPC]
        public void RPC_SyncSetTime(float time)
        {
            SyncedGameTimeManager.HandleSyncSetTime(time);
        }

        [PunRPC]
        public void RPC_SyncStartTime()
        {
            SyncedGameTimeManager.HandleSyncStartTime();
        }

        [PunRPC]
        public void RPC_SyncPauseTime()
        {
            SyncedGameTimeManager.HandleSyncPauseTime();
        }

        [PunRPC]
        public void RPC_SyncResetTime()
        {
            SyncedGameTimeManager.HandleSyncResetTime();
        }

        [PunRPC]
        public void RPC_BossSpawn(string bossName)
        {
            SyncedGameTimeManager.HandleBossSpawn(bossName);
        }

        // ============================================================
        // PlayerController RPC
        // ============================================================

        [PunRPC]
        public void NoticeOtherPlayerDamage(string playerId, float maxHP, float currentHP)
        {
            if (EventChannelLocator.MainContainer?.healthUpdateChannel != null)
            {
                EventChannelLocator.MainContainer.healthUpdateChannel.Raise(
                    HealthUpdateData.OtherPlayer(playerId, maxHP, currentHP));
            }
        }

        [PunRPC]
        public void RPC_SyncPlayerElement(int actorNumber, int elementInt)
        {
            PlayerController.HandleSyncPlayerElement(actorNumber, elementInt);
        }

        [PunRPC]
        public void NoticePlayerDeath(int actorNumber)
        {
            PlayerController.HandlePlayerDeath(actorNumber);
        }

        // ============================================================
        // WizardBoy RPC
        // ============================================================

        [PunRPC]
        public void RPC_InitElementPool(int viewID, int elementInt)
        {
            var go = NetworkServiceLocator.ObjectService.FindByViewID(viewID);
            if (go != null)
            {
                var wizardBoy = go.GetComponent<WizardBoy>();
                if (wizardBoy != null)
                {
                    wizardBoy.HandleInitElementPool(elementInt);
                }
            }
        }

        // ============================================================
        // Boss_Horror (SpiderBoss) RPC
        // ============================================================

        [PunRPC]
        public void RPC_SyncPlayerTarget(int targetViewID)
        {
            var boss = GetSpiderBoss();
            if (boss != null)
            {
                boss.HandleSyncPlayerTarget(targetViewID);
            }
        }

        [PunRPC]
        public void RPC_SyncTriggerAnim(string animName)
        {
            var boss = GetSpiderBoss();
            if (boss != null)
            {
                boss.HandleSyncTriggerAnim(animName);
            }
        }

        // ============================================================
        // Ball Robot_Blue RPC
        // ============================================================

        [PunRPC]
        public void RPC_PlayTriggerAnimation(int viewID, string triggerName)
        {
            var go = NetworkServiceLocator.ObjectService.FindByViewID(viewID);
            if (go != null)
            {
                var ball = go.GetComponent<BallRobot_Blue>();
                if (ball != null)
                {
                    ball.HandlePlayTriggerAnimation(triggerName);
                }
            }
        }

        [PunRPC]
        public void RPC_OnPushed(int viewID, Vector3 pushDir, float moveDist)
        {
            var go = NetworkServiceLocator.ObjectService.FindByViewID(viewID);
            if (go != null)
            {
                var ball = go.GetComponent<BallRobot_Blue>();
                if (ball != null)
                {
                    ball.HandleOnPushed(pushDir, moveDist);
                }
            }
        }

        [PunRPC]
        public void RPC_StartTransfer(int viewID)
        {
            var go = NetworkServiceLocator.ObjectService.FindByViewID(viewID);
            if (go != null)
            {
                var ball = go.GetComponent<BallRobot_Blue>();
                if (ball != null)
                {
                    ball.HandleStartTransfer();
                }
            }
        }

        // ============================================================
        // IDomainRpcService 实现（供 Domain 层通过接口调用，消除直接依赖）
        // ============================================================

        /// <summary>
        /// RPC：非房主端请求房主销毁指定怪物（处理房主端未检测到死亡的情况）
        /// </summary>
        [PunRPC]
        public void RPC_RequestEnemyDestroy(int viewID)
        {
            var go = NetworkServiceLocator.ObjectService.FindByViewID(viewID);
            if (go != null)
            {
                PhotonNetwork.Destroy(go);
            }
        }

        /// <summary>
        /// 通过此 Bridge 的 PhotonView 发送 RPC 到指定目标
        /// </summary>
        public void InvokeRPC(string methodName, NetworkTarget target, params object[] parameters)
        {
            if (photonView == null)
            {
                Debug.LogWarning($"[DomainRpcBridge] photonView is null, cannot send RPC {methodName}");
                return;
            }
            photonView.RPC(methodName, NetworkTargetMapper.ToRpcTarget(target), parameters);
        }
    }
}

