        // 鐩愬€硷紙鍥哄畾锛屽鍔犵牬瑙ｉ毦搴︼級
        private static readonly byte[] SALT = new byte[] { 0x5A, 0x6B, 0x7C, 0x8D, 0x9E, 0xAF, 0xB0, 0xC1 };

        // 杩唬娆℃暟锛堣秺楂樿秺瀹夊叏锛屼絾瓒婃參锛?
        private const int ITERATIONS = 10000;

